/*sidebar:recorder*/ (() => {
  const w = window;
  const write = (record) => w.__oracleWrite(JSON.stringify(record));
  const tree = w.__oracleTree;
  const sideBar = document.getElementsByClassName("side-bar")[0];
  w.addEventListener("scroll", (event) => {
    if (event.target === sideBar) write({ sb: "scroll" });
  }, true);
  const search = document.getElementsByClassName("side-bar-search")[0];
  w.addEventListener("blur", (event) => {
    if (event.target === search) write({ sb: "blur" });
  }, true);
  w.addEventListener("mousedown", (event) => {
    if (event.target instanceof Element && event.target.closest(".field-item-label") !== null) {
      write({ sb: "mousedown", offset: tree([event.offsetX, event.offsetY]) });
    }
  }, true);
})()
